        "question": "Which of the following statements about recording the receipt of goods are\ncorrect?\n1. Suppliers issue a delivery note showing the details of goods despatched from\nthe supplier’s warehouse and delivered to the customer\n2. The goods inward (receiving) department records the goods in the system\nwhen deliveries from suppliers arrive at the warehouse to confirm that the\ngoods have been received\n3. The record of goods received is matched to the purchase invoice and\npurchase order before the invoice is paid",
