        "answerText": "C",
        "explanation": "Issue of direct materials from stores to production (work-in-progress):\nDr Work-In-Progress Control\nCr Materials Control\n(3) shows the correct credit entry in the Materials Control account.\nUpdated 23/10/25",
        "sourcePage": 20
