        "context": "Total annual cost of holding inventory is $3,000.\nTotal annual holding cost = (Buffer inventory +\nEOQ) × Annual holding cost\nper component = (500 +\n× 2,000) × $2 = $3000\nAlpha Co buys material X from a supplier that is located next to its factory. When\nAlpha places an order for material X, the supplier sets up a special production run,\nand it can take several days for the order to be fulfilled. The supplier delivers\nmaterial X to Alpha Co in small batches from the time the order is placed until the\norder is complete.\nAlpha currently uses the economic order quantity model to determine the order\nquantity of material X, but a new management accountant has suggested that the\neconomic batch quantity model (EBQ) would be more appropriate. This would have\nno effect on the total quantity of material X used during the year.",
