        "id": "ch6-q7",
        "number": 7,
        "type": "numeric",
        "context": "Profit under marginal costing is 464,000 − 96,000 = $368000.\nClosing inventory = 20,000 − 18,000 = 2,000 units\nAbsorption cost will include $96,000 of the period’s fixed production overhead\n(2,000 units × 4 labour hours × $12 per hour) in the valuation of closing inventory.\nUnder standard marginal costing this $96,000 would be charged against the\nperiod’s profit resulting in a profit $96,000 lower than $464,000.\nA company has budgeted the following unit costs and revenue of a product:\n$\nSales price\nVariable production cost\nFixed production cost\nIn the most recent period, 2,000 units were produced and 1,000 units were sold.\nActual sales price, variable production cost per unit and total fixed production costs\nwere all as budgeted. Fixed production costs were over absorbed by $4,000. There\nwas no opening inventory for the period.",
        "question": "What would be the reduction in profit for the period if the company had used\nmarginal costing rather than absorption costing? (Answer in $)",
        "options": [],
        "statements": [],
        "correct": "$10000",
        "answerText": "$10000",
        "explanation": "Reduction in profit if marginal costing had been used is $10000.\nIncrease in finished goods inventory (2,000 units produced less 1,000 units sold) ×\nfixed production cost per unit = 1,000 × $10 = $10,000\nTutorial note: Under or over absorption adjustments do not cause a difference\nbetween marginal and absorption costing profits. They simply ensure that\nabsorption costing charges the same amount of fixed overhead as marginal costing.\nThe following data is available on the production and sales for the first three years of\na company’s new product:\nYear 1 Year 2 Year 3\nProduction units\n5,000 6,000\n4,000\nSales units\n4,000 6,000\n5,000\nVariable costs per unit, selling price and total fixed costs per year were constant\nover the three-year period. The company is considering the use of either marginal or\nabsorption costing.",
        "sourcePage": 51
