        "context": "Reduction in profit if marginal costing had been used is $10000.\nIncrease in finished goods inventory (2,000 units produced less 1,000 units sold) ×\nfixed production cost per unit = 1,000 × $10 = $10,000\nTutorial note: Under or over absorption adjustments do not cause a difference\nbetween marginal and absorption costing profits. They simply ensure that\nabsorption costing charges the same amount of fixed overhead as marginal costing.\nThe following data is available on the production and sales for the first three years of\na company’s new product:\nYear 1 Year 2 Year 3\nProduction units\n5,000 6,000\n4,000\nSales units\n4,000 6,000\n5,000\nVariable costs per unit, selling price and total fixed costs per year were constant\nover the three-year period. The company is considering the use of either marginal or\nabsorption costing.",
        "question": "Which of the following statements is/are true?\n1. Absorption costing will show a lower profit than marginal costing in Year 1\n2. Marginal costing will show a lower closing inventory valuation than absorption\ncosting in Year 2\n3. Total profit over the three-year period will be the same under both methods",
