        "context": "This treats the by-product in the same way as a joint product and is clearly\ninappropriate. No knowledge of the other approaches is required to appreciate that\nthis approach is incorrect.\nIn a period, a process produced 2,000 kg of a main product and 400 kg of a by-\nproduct. The cost of production was $5,000. 1,800 kg of the main product were sold\nat $10 per kg and all of the by-product produced was sold for $1per kg. There was\nno opening inventory.",
        "question": "If the sales income of the by-product is deducted from the cost of production,\nwhat is the profit for the period? (Answer in $)",
