        "explanation": "Distribution costs are those costs incurred in making completed products ready for\ndispatch and their delivery to customers. Thus the warehouse rental and\ndepreciation of delivery vehicles are distribution costs but the sales commission is\nclearly a selling cost.\nThe following observations of output and cost have been made:\nOutput (units)\nCost\n8,000\n$39,400\n20,000\n$68,000\nIt is known that at output levels above 15,000 units, variable cost per unit drops by\n$1 per unit for all subsequent units produced.",
        "sourcePage": 74
