        "answerText": "A",
        "explanation": "Since the variable cost is $1 lower per unit after 15,000 units, the total cost for\n20,000 units must be adjusted first before using the high-low method.\nTotal cost for 20,000 = $68,000 + (20,000 − 15,000) units × $1 = $73,000.\nVariable cost per unit (assuming no change in variable cost) =\n($73,000 − $39,400) ÷ (20,000 − 8,000) units = $2.80\nVariable cost per unit after 15,000 units is then $1 lower = $2.80 − $1.00 = $1.80.",
        "sourcePage": 74
