        "context": "24. Identify whether the following costs would be classified as production or non-\nproduction costs.\nProduction\nNon Production\nAdministration\nProduction\nNon Production\nDirect Labour\nProduction\nNon Production\nDistribution Costs\nProduction\nNon Production\nDirect expenses\nIt is important to distinguish between production and non-production costs when\nvaluing output and inventories. This is because the value of a unit of inventory or a\ncompleted unit of product (output) should only include production costs (the costs\nassociated with making the product).",
