        "explanation": "Tutorial note: ABC is a method of accounting for overheads and therefore has no\neffect on direct costs. The cost allocated and apportioned to each activity is known\nas the “cost pool” and the action that causes the overhead to be incurred is known\nas the “cost driver”.",
