        "explanation": "A is a sunk cost so is not relevant. Depreciation is not a cash flow, so C is not\ncorrect. The original cost of raw materials is not relevant as that is a historic cost, so\nD is incorrect. B is a relevant cash flow as it relates specifically to the project.\nThe following statements relate to the concept of relevant cash flows in decision\nmaking:\n1. Materials can never have an opportunity cost whereas labour can\n2. An annual depreciation charge is not a relevant cash flow\n3. Fixed costs would have a relevant cash flow element if a decision causes a\nchange in their total expenditure",
        "sourcePage": 113
