        "context": "An annual budget set before the start of a year based on a single level of estimated\nTRU\nFalse\nsales and production volumes is called a fixed budget\nE\nA company has prepared flexed budgets at two activity levels. The cost per unit of\nthree costs is given below. All three costs behave in a linear manner with respect to\nactivity.\nActivity level (units)\n10,000\n15,000\nCost\nX\n$3.0 per unit $2.0 per unit\nY\n$1.0 per unit $1.0 per unit\nZ\n$3.5 per unit $3.0 per unit",
        "question": "Is each of the costs variable, semi-variable or fixed?\nX\nY\nZ",
