        "answerText": "C",
        "explanation": "Semi variable means that there is a fixed cost for total production and a variable cost\nper unit of production. Considering the make-up of profit, if production is doubled −\ntotal revenue, total variable cost and hence total contribution will all double. Hence C\nis correct (and D is incorrect). B is clearly incorrect as if production is doubled fixed\ncost per unit will be halved. A could only be true if there were no fixed costs; so is\nclearly incorrect in this case.\nTutorial note: “Inventing” some simple figures to test the validity of the statements\non offer may be helpful:\nFor example, assuming a sales price of $10 per unit, a unit variable cost of $2 and a\nfixed cost of $4,000:\nSales units\n1,000\n2,000\n$\n$\n10,00\nSales revenue\n20,000\nVariable cost\n2,000 4,000\nTotal contribution\n8,000 16,000\nFixed cost\n2,000 2,000\nOperating profit\n6,000 14,000\nBudgeted costs and revenues for an output level of 4,000 units are given below. It is\nknown that after an output level of 5,000 units there is a step up in fixed costs of\n$1,000.\n$ per unit\nSales price\nVariable cost\nFixed cost\nProfit",
