        "explanation": "The fixed overhead volume variance is the difference between standard hours\nrequired for actual production and budgeted hours, multiplied by the standard fixed\noverhead absorption rate.\nThe fixed overhead capacity variance is the difference between actual hours worked\nand budgeted hours, multiplied by the standard fixed overhead absorption rate.\nStandard hours for actual production are not given, so we cannot solve the question\nby analysing the volume variance. However, we do know actual machine hours\nused, so the question can be solved by analysing the capacity variance.\nCapacity variance = (Actual hours − Budgeted hours) × standard fixed overhead per\nhour\nCapacity variance = $3,600 favourable (Actual hours − Budgeted hours) × standard\nfixed overhead per hour = $3,600 favourable\nOf the elements in the capacity variance, we know the actual hours (1,760) and the\nstandard fixed overhead per hour ($20). Insert these figures in to the calculation and\nsolve for the budgeted hours:\n(1,760 hours − Budgeted hours) × $20 = $3,600\nFrom this calculate the budgeted hours: (1,760 − ($3,600/$20)) = 1,580 hours\nA company has calculated a $10,000 adverse direct material variance by subtracting\nits flexed budget direct material cost from its actual direct material cost for the\nperiod.",
