        "number": 7,
        "type": "matrix",
        "context": "A company has current assets of $1.8 million, including inventory of $0.5 million, and current liabilities of $1 million.",
        "question": "What would be the effects on the current ratio and acid test ratio if the company purchased additional raw material inventory on three months’ credit?",
        "options": [],
