        "type": "single",
        "context": "Efficiency is the measure of output related to input. (Economy is the measure of cost\nrelated to input and effectiveness the measure of output related to objectives.)\nA division earns an annual operating profit of $200,000 and has a return on\ninvestment of 20% per year.",
