        "explanation": "($200,000 − ($200,000 ÷ 0.2 × 0.15)) = $50,000\nThe performance of a publicly funded hospital is monitored using measures based\nupon the “three Es”. The most important performance measure is considered to be\nthe achievement of hospital targets for the successful treatment of patients.",
