        "answerText": "B",
        "explanation": "Effectiveness is the measure of output related to objectives.\nA division has a capital employed of $2,000,000 and earns an operating profit of\n$600,000. It is considering a project that will increase operating profit by $20,000\nbut would increase its capital employed by $80,000. A rate of 15% is used to\ncompute interest on capital employed.",
        "sourcePage": 211
