        "answerText": "C",
        "explanation": "Functional benchmarking involves comparing the performance of a specific function\nwith the market leader in that area.\nA company has a capital employed of $300,000. It has a cost of capital of 8% per\nyear. Its residual income is $51,000.",
        "sourcePage": 213
