        "number": 10,
        "type": "numeric",
        "context": "Functional benchmarking involves comparing the performance of a specific function\nwith the market leader in that area.\nA company has a capital employed of $300,000. It has a cost of capital of 8% per\nyear. Its residual income is $51,000.",
        "question": "What is the company’s return on capital employed? (Answer in %)",
        "options": [],
        "statements": [],
        "correct": "25%",
        "answerText": "25%",
        "explanation": "Approach: The question does not give the profit before interest and tax. However, RI\nis given. RI = PBIT less imputed interest. By adding the imputed interest back to the\nRI, the PBIT can be calculated:\n$\nResidual income\n51,000\nAdd back the imputed finance charge ($300,000 ×\n24,000\n8%)\nOperating profit\n75,000\n⇒ ROCE = 75,000 ÷ 300,000 = 25 %",
        "sourcePage": 214
